60|        .frame(minWidth: 900, minHeight: 560)
61|        .preferredColorScheme(preferredColorScheme)
62|        .onAppear {
63|            DispatchQueue.main.async {
64|                guard let window = NSApp.keyWindow
65|                    ?? NSApp.windows.first(where: \.isVisible)
66|                    ?? NSApp.windows.first else { return }
67|                let label = model.hasDocument ? "归档工作台" : "欢迎"
