72|                window.contentView?.setAccessibilityIdentifier("归档工作台窗口内容")
73|                if minimumWindow, let screen = window.screen ?? NSScreen.main {
74|                    let visibleFrame = screen.visibleFrame
75|                    let size = NSSize(width: 900, height: min(700, visibleFrame.height))
76|                    window.setFrame(
77|                        NSRect(
