140|                    paneLabel = "归档信息"
141|                } else {
142|                    paneLabel = "归档内容"
143|                }
144|                pane.setAccessibilityLabel(paneLabel)
145|                pane.setAccessibilityIdentifier("\(paneLabel)容器")
146|            }
147|        }
148|        for subview in view.subviews {
149|            labelSplitViewContainers(in: subview)
