31|private struct PDFKitCanvas: NSViewRepresentable {
32|    let document: PDFDocument?
33|
34|    func makeNSView(context: Context) -> PDFView {
35|        let view = PDFView()
36|        view.autoScales = true
37|        view.document = document
38|        updateAccessibility(in: view)
39|        DispatchQueue.main.async { updateAccessibility(in: view) }
40|        return view
41|    }
42|
43|    func updateNSView(_ nsView: PDFView, context: Context) {
44|        if nsView.document !== document { nsView.document = document }
45|        updateAccessibility(in: nsView)
46|        DispatchQueue.main.async { updateAccessibility(in: nsView) }
47|    }
48|
49|    private func updateAccessibility(in view: NSView) {
50|        let pageCount = document?.pageCount ?? 0
51|        view.setAccessibilityLabel("PDFKit 安全缓存预览，\(pageCount) 页")
52|        labelPDFHierarchy(in: view, pageCount: pageCount)
53|        labelPDFVirtualElements(view.accessibilityChildren() ?? [], pageCount: pageCount)
54|    }
55|
56|    private func labelPDFHierarchy(in view: NSView, pageCount: Int) {
57|        let role: NSAccessibility.Role? = view.accessibilityRole()
58|        let label: String? = view.accessibilityLabel()
59|        if role == .group, label?.isEmpty != false {
60|            view.setAccessibilityLabel("PDF 文档页面内容，共 \(pageCount) 页")
61|            view.setAccessibilityIdentifier("PDF 文档页面内容")
62|        }
63|        for subview in view.subviews {
64|            labelPDFHierarchy(in: subview, pageCount: pageCount)
65|        }
66|    }
67|
68|    private func labelPDFVirtualElements(_ elements: [Any], pageCount: Int) {
69|        for element in elements {
70|            guard let virtualElement = element as? NSObject,
71|                  virtualElement.responds(to: NSSelectorFromString("accessibilityLabel")) else { continue }
72|            let role = virtualElement.value(forKey: "accessibilityRole") as? String
73|            let label = virtualElement.value(forKey: "accessibilityLabel") as? String
74|            if label?.isEmpty != false, let fallback = fallbackLabel(forRole: role, pageCount: pageCount) {
75|                virtualElement.setValue(fallback, forKey: "accessibilityLabel")
76|            }
77|            let children = virtualElement.value(forKey: "accessibilityChildren") as? [Any] ?? []
78|            labelPDFVirtualElements(children, pageCount: pageCount)
79|        }
80|    }
81|
82|    private func fallbackLabel(forRole role: String?, pageCount: Int) -> String? {
83|        switch role {
84|        case NSAccessibility.Role.group.rawValue:
85|            return "PDF 页面容器，共 \(pageCount) 页"
86|        case NSAccessibility.Role.button.rawValue:
87|            return "PDF 滚动控制"
88|        case "AXIncrementArrow":
89|            return "向前滚动 PDF"
90|        case "AXDecrementArrow":
91|            return "向后滚动 PDF"
92|        default:
93|            return nil
94|        }
95|    }
